{
    "service_name": "my-service",
    "rsa": null,
    "json_schemas": [
        {
            "type": "ACCOUNT",
            "schema_content": {
                "$schema": "http://json-schema.org/draft-07/schema#",
                "$id": "https://example.com/config.schema.json",
                "title": "Subscription Configuration",
                "type": "object",
                "properties": {
                    "subscriptionKey": {
                        "type": "string",
                        "description": "The unique API key for the subscription",
                        "minLength": 1
                    },
                    "environment": {
                        "type": "string",
                        "description": "The target deployment environment",
                        "enum": [
                            "development",
                            "staging",
                            "production"
                        ]
                    }
                },
                "required": [
                    "subscriptionKey",
                    "environment"
                ]
            }
        },
        {
            "type": "user",
            "schema_content": {
                "$schema": "http://json-schema.org/draft-07/schema#",
                "$id": "https://example.com/config.schema.json",
                "title": "Subscription Configuration",
                "type": "object",
                "properties": {
                    "subscriptionKey": {
                        "type": "string",
                        "description": "The unique API key for the subscription",
                        "minLength": 1
                    },
                    "environment": {
                        "type": "string",
                        "description": "The target deployment environment",
                        "enum": [
                            "development",
                            "staging",
                            "production"
                        ]
                    },
                    "role": {
                        "type": "string",
                        "description": "The agent role",
                        "minLength": 1
                    }
                },
                "required": [
                    "subscriptionKey",
                    "environment"
                ]
            }
        }
    ]
}
